<section class="page-hero"><p class="eyebrow"><?= e(country()->name()) ?></p><h1>Licence information</h1></section><section class="section"><?php if(!$license||empty($license['document_path'])): ?><div class="empty-state"><h2>No licence document uploaded</h2><p>We do not display recreated or synthetic licences.</p></div><?php else: ?><div class="grid two"><article class="card"><h2><?= e($license['license_name']??'Current licence') ?></h2><dl class="detail-list"><dt>Regulator</dt><dd><?= e($license['regulator_name']??'—') ?></dd><dt>Number</dt><dd><?= e($license['license_number']??'—') ?></dd><dt>Status</dt><dd><span class="badge"><?= e($license['calculated_status']) ?></span></dd><dt>Issue date</dt><dd><?= e($license['issue_date']??'—') ?></dd><dt>Expiry date</dt><dd><?= e($license['expiry_date']??'—') ?></dd></dl><p><a class="button" target="_blank" href="<?= e(route('license.document',['license'=>$license['id']])) ?>">Open document</a> <a class="text-link" href="<?= e(route('license.document',['license'=>$license['id']]).'?download=1') ?>">Download</a></p></article><article class="card license-viewer"><?php if(str_starts_with((string)$license['mime_type'],'image/')): ?><img src="<?= e(route('license.document',['license'=>$license['id']])) ?>" alt="<?= e($license['license_name']??'Licence document') ?>"><?php else: ?><iframe title="Licence document" src="<?= e(route('license.document',['license'=>$license['id']])) ?>"></iframe><?php endif;?></article></div><?php endif;?></section>
